 for p in sorted(Path('results/run100',area).glob('*.jsonl'),key=lambda x:int(x.stem)):
  rows=[json.loads(x) for x in p.read_text().splitlines()]
  encs=tok.encode_batch([r['output'] for r in rows],add_special_tokens=False)
  lens=[len(e.ids) for e in encs]
  repeated=[]
  for r in rows:
   lines=[x.strip() for x in r['output'].splitlines() if len(x.strip())>=15]
   cnt=collections.Counter(lines)
   repeated.append(max(cnt.values(),default=0)>=4)
  cap=[l>=511 for l in lens]
  boxes=[bool(re.search(r'\\boxed\s*\{',r['output'])) for r in rows]
  print('\n',p,'n',len(rows),'score',sum(r['score'] for r in rows),statistics.mean(r['score'] for r in rows),'tokens mean,median,max',statistics.mean(lens),statistics.median(lens),max(lens))
  print('511/512',collections.Counter(l for l in lens if l>=511),'repeat>=4',sum(repeated),'box',sum(boxes),'field agrees',all(r['score']==r['acc']==r.get('reward',r['score']) for r in rows))
  for name,mask in [('cap',cap),('below_cap',[not x for x in cap]),('repeated',repeated),('box',boxes),('unboxed',[not x for x in boxes])]:
